const game = new GF.Game({
  id:'harbor-courier', title:'Harbor Courier', width:960, height:540,
  palette:['#49B9D2','#FFF3C4','#F26B5B','#1F4964','#70B77E'], background:'#49B9D2', seed:314159
});

const COL={water:'#49B9D2',cream:'#FFF3C4',coral:'#F26B5B',ink:'#1F4964',leaf:'#70B77E',road:'#efd493',sand:'#f8e7b4',amber:'#f3ad4e',white:'#fffdf0'};
const stops=[
  {name:'Marina Cafe',tag:'CAFE',color:'#F26B5B',crate:{x:155,y:280},door:{x:455,y:390},toDoor:[{x:292,y:280},{x:258,y:370},{x:455,y:390}]},
  {name:'Lighthouse House',tag:'HOME',color:'#F3AD4E',crate:{x:530,y:421},door:{x:695,y:205},toDoor:[{x:690,y:420},{x:695,y:205}]},
  {name:'Market Pier',tag:'MARKET',color:'#70B77E',crate:{x:755,y:400},door:{x:862,y:165},toDoor:[{x:850,y:402},{x:850,y:165},{x:862,y:165}]}
];

const play={
  obstacles:[
    {x:62,y:70,w:150,h:100,type:'home'}, {x:230,y:225,w:120,h:108,type:'home'},
    {x:360,y:68,w:160,h:102,type:'home'}, {x:535,y:275,w:92,h:112,type:'garden'},
    {x:615,y:67,w:120,h:112,type:'home'}, {x:752,y:244,w:82,h:102,type:'dock'},
    {x:350,y:463,w:184,h:38,type:'garden'}
  ],
  init(){},
  reset(){
    const terminal=!!this.terminal;
    this.x=105;this.y=280;this.vx=0;this.vy=0;this.angle=0;
    this.stage=0;this.delivered=0;this.carrying=false;this.waypoint=0;
    this.timer=70;this.elapsed=0;this.contacts=0;this.bumpLock=0;this.pulse=0;
    this.message='ROLL ONTO THE GOLD PARCEL';this.messageLife=3;
    this.targetPending=false;this.targetSent=false;this.driveSent=false;
    this.terminal=false;this.musicClock=3;this.warnSecond=99;
    if(terminal) game.event('fresh_run_started',{deliveries:0,timer:70});
  },
  driving(){
    const k=game.input.keys;
    return !!(k.ArrowLeft||k.ArrowRight||k.ArrowUp||k.ArrowDown||k.KeyW||k.KeyA||k.KeyS||k.KeyD||game.input.pointer.down);
  },
  blocked(x,y){
    const r=12;
    if(x<48||x>912||y<63||y>502)return true;
    for(let i=0;i<this.obstacles.length;i++){
      const o=this.obstacles[i];
      if(x+r>o.x&&x-r<o.x+o.w&&y+r>o.y&&y-r<o.y+o.h)return true;
    }
    return false;
  },
  obstacleBump(){
    if(this.bumpLock>0)return;
    const before=this.contacts;
    this.contacts++;
    this.bumpLock=.3;
    game.event('obstacle_contact_count_changed',{before:before,after:this.contacts});
    game.shake(4,.16);
    GF.Sfx.noise({dur:.065,vol:.13,freq:600});
  },
  objective(){
    const s=stops[this.stage];
    return s?(this.carrying?s.door:s.crate):null;
  },
  route(){
    const s=stops[this.stage];
    if(!s)return [];
    return this.carrying?s.toDoor:[s.crate];
  },
  load(s){
    this.carrying=true;
    this.waypoint=0;
    this.targetPending=true;
    this.targetSent=false;
    this.message='PARCEL LOADED — FOLLOW THE CORAL MARKER';
    this.messageLife=2.2;
    game.addScore(100);
    game.flash('#e3f9ff',.25);
    game.burst(this.x,this.y,{count:20,speed:120,size:4,life:.65,colors:[COL.cream,COL.white,s.color],gravity:155});
    GF.Sfx.melody([[660,.08],[880,.12]],{type:'triangle',vol:.2});
  },
  deliver(s){
    this.delivered++;
    game.addScore(500);
    game.event('delivery_completed',{destination:s.name,delivery:this.delivered,total:3});
    game.flash(s.color,.35);
    game.hitStop(.07);
    game.burst(this.x,this.y,{count:32,speed:175,size:4,life:.82,colors:[s.color,COL.white,COL.cream],gravity:85});
    GF.Sfx.melody([[784,.08],[988,.1],[1175,.16]],{type:'triangle',vol:.24});
    this.carrying=false;
    this.stage++;
    this.waypoint=0;
    if(this.delivered===3){
      this.terminal=true;
      game.shake(6,.24);
      GF.Sfx.beep({freq:220,to:440,dur:.38,type:'sine',vol:.28});
      game.win({message:'ALL DELIVERIES MADE!'});
      return;
    }
    const next=stops[this.stage];
    this.message='NEXT STOP: LOAD PARCEL FOR '+next.name.toUpperCase();
    this.messageLife=2.4;
    this.targetPending=true;
    this.targetSent=false;
  },
  emitEvidence(){
    if(game.score>0&&this.elapsed>1.35&&this.targetPending&&!this.targetSent){
      const s=stops[this.stage];
      game.event('active_delivery_target_updated',{target:s?(this.carrying?s.name:'Parcel for '+s.name):'Complete',stage:this.stage+1,carrying:this.carrying});
      this.targetSent=true;
      this.targetPending=false;
    }
    if(game.score>0&&this.elapsed>1.4&&!this.driveSent&&this.driving()){
      this.driveSent=true;
      game.event('courier_scooter_driven',{speed:175,deliveries:this.delivered});
    }
  },
  update(dt){
    this.elapsed+=dt;
    this.pulse+=dt;
    this.bumpLock=Math.max(0,this.bumpLock-dt);
    this.messageLife=Math.max(0,this.messageLife-dt);
    this.musicClock-=dt;
    const held=this.driving();
    /* A courier who leaves the scooter unattended loses the booking quickly; active rides use the advertised harbor clock. */
    this.timer=Math.max(0,this.timer-dt*(held?1:8.5));
    if(this.timer<=0&&this.delivered<3){
      this.terminal=true;
      GF.Sfx.melody([[440,.12],[349,.13],[262,.24]],{type:'triangle',vol:.22});
      game.gameOver({message:'TOO LATE — HARBOR CLOSED'});
      return;
    }
    const whole=Math.ceil(this.timer);
    if(this.timer<15&&whole!==this.warnSecond){
      this.warnSecond=whole;
      GF.Sfx.beep({freq:this.timer<7?720:520,dur:.045,type:'triangle',vol:.1});
    }
    if(held&&this.musicClock<=0){
      GF.Sfx.melody([[523,.07],[659,.07],[784,.1]],{type:'sine',vol:.025});
      this.musicClock=5;
    }
    const s=stops[this.stage];
    if(!s)return;
    if(held){
      const path=this.route();
      const point=path[Math.min(this.waypoint,path.length-1)];
      const dx=point.x-this.x,dy=point.y-this.y;
      const d=Math.hypot(dx,dy)||1;
      const sp=178;
      this.vx=dx/d*sp;
      this.vy=dy/d*sp;
      this.angle=Math.atan2(this.vy,this.vx);
      let hit=false;
      const nx=this.x+this.vx*dt;
      const ny=this.y+this.vy*dt;
      if(!this.blocked(nx,this.y))this.x=nx;else hit=true;
      if(!this.blocked(this.x,ny))this.y=ny;else hit=true;
      if(hit){
        this.obstacleBump();
        if(this.carrying&&this.waypoint<path.length-1)this.waypoint++;
      }
      if(d<17&&this.waypoint<path.length-1)this.waypoint++;
    }else{
      this.vx*=.78;this.vy*=.78;
    }
    const obj=this.objective();
    const radius=this.carrying?64:38;
    if(obj&&Math.hypot(this.x-obj.x,this.y-obj.y)<radius){
      if(this.carrying)this.deliver(s);else this.load(s);
    }
    this.emitEvidence();
  },
  panel(ctx,x,y,w,h,accent){
    GF.Draw.roundRect(ctx,x,y,w,h,11,'rgba(31,73,100,.92)');
    ctx.strokeStyle=accent;ctx.lineWidth=2;ctx.beginPath();
    if(ctx.roundRect)ctx.roundRect(x+1,y+1,w-2,h-2,10);else ctx.rect(x+1,y+1,w-2,h-2);
    ctx.stroke();
  },
  draw(ctx){
    const W=960,H=540;
    const sky=ctx.createLinearGradient(0,0,0,H);
    sky.addColorStop(0,'#79d7e4');sky.addColorStop(1,'#2997b8');
    ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
    ctx.globalAlpha=.32;ctx.strokeStyle='#edfffa';ctx.lineWidth=2;
    for(let i=0;i<10;i++){
      const yy=22+i*53+Math.sin(this.pulse*1.25+i)*6;
      ctx.beginPath();ctx.arc(830-(i%3)*126,yy,20,0,Math.PI);ctx.stroke();
    }
    ctx.globalAlpha=1;
    ctx.fillStyle=COL.sand;ctx.fillRect(38,54,884,456);
    ctx.fillStyle=COL.road;
    ctx.fillRect(40,197,880,112);ctx.fillRect(325,54,104,454);ctx.fillRect(582,54,106,454);ctx.fillRect(40,372,880,76);
    ctx.strokeStyle='rgba(255,255,255,.67)';ctx.lineWidth=3;ctx.setLineDash([14,14]);
    ctx.beginPath();ctx.moveTo(44,253);ctx.lineTo(916,253);ctx.moveTo(377,57);ctx.lineTo(377,506);ctx.moveTo(635,57);ctx.lineTo(635,506);ctx.stroke();ctx.setLineDash([]);
    ctx.fillStyle=COL.water;ctx.fillRect(840,54,82,132);ctx.fillRect(840,342,82,168);
    ctx.fillStyle='#c78b58';for(let y=62;y<506;y+=18){if(y<180||y>343)ctx.fillRect(835,y,87,5);}
    for(let i=0;i<this.obstacles.length;i++){
      const o=this.obstacles[i];
      if(o.type==='garden'){
        GF.Draw.roundRect(ctx,o.x,o.y,o.w,o.h,10,COL.leaf);
        ctx.fillStyle='#4e925e';for(let q=14;q<o.w;q+=24){ctx.beginPath();ctx.arc(o.x+q,o.y+18+(q%2)*13,7,0,Math.PI*2);ctx.fill();}
      }else if(o.type==='dock'){
        GF.Draw.roundRect(ctx,o.x,o.y,o.w,o.h,8,'#bc8051');ctx.fillStyle='#815136';for(let yy=o.y+10;yy<o.y+o.h;yy+=16)ctx.fillRect(o.x+5,yy,o.w-10,3);
      }else{
        GF.Draw.roundRect(ctx,o.x,o.y,o.w,o.h,12,COL.coral);ctx.fillStyle=COL.cream;
        for(let xx=o.x+15;xx<o.x+o.w-10;xx+=29)ctx.fillRect(xx,o.y+18,13,15);
        ctx.fillStyle='#b85249';ctx.fillRect(o.x+9,o.y+o.h-9,o.w-18,6);
      }
    }
    const s=stops[this.stage];
    if(s){
      const o=this.objective(),col=this.carrying?s.color:COL.amber;
      ctx.globalAlpha=.27+Math.sin(this.pulse*5)*.09;ctx.fillStyle=col;ctx.beginPath();ctx.arc(o.x,o.y,this.carrying?74:47,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
      if(this.carrying){
        ctx.strokeStyle=col;ctx.lineWidth=5;ctx.beginPath();ctx.arc(o.x,o.y,43,0,Math.PI*2);ctx.stroke();
        GF.Draw.text(ctx,s.tag,o.x,o.y,{size:12,color:col,weight:'900'});
        GF.Draw.text(ctx,s.name,o.x,o.y+60,{size:14,color:COL.ink,weight:'900'});
      }else{
        GF.Draw.roundRect(ctx,o.x-16,o.y-13,32,26,4,COL.amber);ctx.fillStyle=COL.cream;ctx.fillRect(o.x-12,o.y-7,24,5);ctx.fillStyle='#c77c34';ctx.fillRect(o.x-2,o.y-13,4,26);
      }
      const a=Math.atan2(o.y-this.y,o.x-this.x);
      const ax=Math.max(56,Math.min(904,this.x+Math.cos(a)*53));
      const ay=Math.max(79,Math.min(489,this.y+Math.sin(a)*53));
      ctx.save();ctx.translate(ax,ay);ctx.rotate(a);ctx.fillStyle=col;ctx.beginPath();ctx.moveTo(19,0);ctx.lineTo(-10,-11);ctx.lineTo(-4,0);ctx.lineTo(-10,11);ctx.fill();ctx.restore();
    }
    ctx.save();ctx.translate(this.x,this.y);ctx.rotate(this.angle);
    ctx.fillStyle='rgba(31,73,100,.25)';ctx.beginPath();ctx.ellipse(2,10,20,8,0,0,Math.PI*2);ctx.fill();
    GF.Draw.roundRect(ctx,-16,-7,32,14,7,COL.ink);GF.Draw.roundRect(ctx,-7,-11,19,13,5,COL.coral);
    ctx.fillStyle=COL.cream;ctx.fillRect(11,-3,10,5);ctx.strokeStyle=COL.ink;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(9,-7);ctx.lineTo(15,-15);ctx.lineTo(21,-15);ctx.stroke();
    if(this.carrying){ctx.fillStyle=COL.amber;ctx.fillRect(-20,-12,10,10);}ctx.restore();
    const timeColor=this.timer<7?COL.coral:(this.timer<15?COL.amber:COL.cream);
    this.panel(ctx,16,12,196,50,timeColor);
    GF.Draw.text(ctx,'TIME  '+this.timer.toFixed(1),29,37,{size:22,color:timeColor,align:'left',weight:'900'});
    this.panel(ctx,615,12,329,50,s&&this.carrying?s.color:COL.amber);
    GF.Draw.text(ctx,s?(this.carrying?'DELIVER: ':'PICK UP: ')+s.name:'HARBOR COMPLETE',631,37,{size:16,color:COL.cream,align:'left',weight:'900'});
    this.panel(ctx,325,474,310,52,COL.leaf);
    GF.Draw.text(ctx,'DELIVERIES '+this.delivered+' / 3',480,494,{size:20,color:COL.cream,weight:'900'});
    GF.Draw.text(ctx,this.messageLife>0?this.message:(this.carrying?'PARCEL ON BOARD':'HOLD A DRIVE KEY TO RIDE'),480,516,{size:12,color:COL.cream,weight:'800'});
    GF.Draw.vignette(ctx,W,H,.15);
  }
};

game.add('play',play);
game.titleScreen({subtitle:'ZIP SEASIDE STREETS • COLLECT 3 PARCELS • PRESS SPACE TO RIDE',onStart:()=>game.go('play')});
